import unittest
from solution import paginate

LOG = ["m%d" % i for i in range(1, 11)]


def gen(seq):
    for x in seq:
        yield x


class OneShot:
    def __init__(self, seq):
        self._it = iter(list(seq))
        self._used = False

    def __iter__(self):
        if self._used:
            raise RuntimeError("iterated twice")
        self._used = True
        return self._it


class BareIterator:
    def __init__(self, seq):
        self._it = iter(list(seq))

    def __iter__(self):
        return self

    def __next__(self):
        return next(self._it)


class Tracked:
    live = 0
    peak = 0

    def __init__(self, i):
        self.i = i
        Tracked.live += 1
        if Tracked.live > Tracked.peak:
            Tracked.peak = Tracked.live

    def __del__(self):
        Tracked.live -= 1


class T(unittest.TestCase):
    def test_generator_pages(self):
        self.assertEqual(paginate(gen(LOG), 1, 3), ["m8", "m9", "m10"])
        self.assertEqual(paginate(gen(LOG), 2, 3), ["m5", "m6", "m7"])
        self.assertEqual(paginate(gen(LOG), 3, 3), ["m2", "m3", "m4"])

    def test_generator_ragged_oldest_page(self):
        self.assertEqual(paginate(gen(LOG), 4, 3), ["m1"])

    def test_generator_past_the_beginning(self):
        self.assertEqual(paginate(gen(LOG), 5, 3), [])
        self.assertEqual(paginate(gen(LOG), 9, 3), [])
        self.assertEqual(paginate(gen(LOG), 10 ** 6, 3), [])

    def test_one_shot_iterable(self):
        self.assertEqual(paginate(OneShot(LOG), 2, 3), ["m5", "m6", "m7"])
        self.assertEqual(paginate(OneShot(LOG), 4, 3), ["m1"])

    def test_bare_iterator_returns_plain_list(self):
        out = paginate(BareIterator(LOG), 1, 4)
        self.assertIsInstance(out, list)
        self.assertEqual(out, ["m7", "m8", "m9", "m10"])

    def test_absurd_page_tiny_stream(self):
        self.assertEqual(paginate(iter(["a", "b", "c", "d", "e"]), 10 ** 9, 3), [])
        self.assertEqual(paginate(iter([]), 10 ** 9, 4), [])
        self.assertEqual(paginate(iter([]), 1, 4), [])
        self.assertEqual(paginate(iter(["a", "b"]), 1, 5), ["a", "b"])
        self.assertEqual(paginate(iter(["a", "b"]), 2, 5), [])

    def test_exact_division_stream(self):
        six = ["m%d" % i for i in range(1, 7)]
        self.assertEqual(paginate(gen(six), 1, 3), ["m4", "m5", "m6"])
        self.assertEqual(paginate(gen(six), 2, 3), ["m1", "m2", "m3"])
        self.assertEqual(paginate(gen(six), 3, 3), [])

    def test_per_page_one_stream(self):
        three = ["m1", "m2", "m3"]
        self.assertEqual(paginate(gen(three), 1, 1), ["m3"])
        self.assertEqual(paginate(gen(three), 2, 1), ["m2"])
        self.assertEqual(paginate(gen(three), 3, 1), ["m1"])
        self.assertEqual(paginate(gen(three), 4, 1), [])

    def test_list_input_still_works_and_untouched(self):
        original = list(LOG)
        self.assertEqual(paginate(LOG, 1, 3), ["m8", "m9", "m10"])
        self.assertEqual(paginate(LOG, 4, 3), ["m1"])
        self.assertEqual(paginate(LOG, 99, 3), [])
        self.assertEqual(LOG, original)

    def test_chronological_order(self):
        data = list(range(50))
        out = paginate(gen(data), 3, 7)
        self.assertEqual(out, [29, 30, 31, 32, 33, 34, 35])
        self.assertTrue(all(out[i] < out[i + 1] for i in range(len(out) - 1)))

    def test_bounded_memory(self):
        N = 200000
        Tracked.live = 0
        Tracked.peak = 0

        def stream():
            for i in range(N):
                yield Tracked(i)

        out = paginate(stream(), 2, 4)
        peak = Tracked.peak
        self.assertEqual([t.i for t in out], [N - 8, N - 7, N - 6, N - 5])
        self.assertLessEqual(peak, 2 * 4 + 16)

