            lvl = 2 if s[i] == DOV else 1
            i += 1
            if i < len(s) and s[i] in (OV, DOV):
                raise AssertionError("two marks on one letter in %r" % s)
        groups[lvl].append(ch)
        if not order or order[-1] != lvl:
            order.append(lvl)
    if order != sorted(set(order), reverse=True):
        raise AssertionError("groups out of order in %r" % s)
    return "".join(groups[2]), "".join(groups[1]), "".join(groups[0])


class T(unittest.TestCase):
