    def test_maximum(self):
        self.assertEqual(
            to_roman(3999999999),
            "M\u033fM\u033fM\u033fC\u033fM\u033fX\u033fC\u033fI\u033fX\u033f"
            "C\u0305M\u0305X\u0305C\u0305I\u0305X\u0305CMXCIX",
        )

    def test_interior_zero_group(self):
        rng = random.Random(1234)
        cases = [1000000, 1000001, 2000000005, 3000000007, 1000000999]
        cases += [rng.randint(1, 3999) * 1000000 + rng.randint(0, 999)
                  for _ in range(120)]
        for n in cases:
            s = to_roman(n)
            self.assertNotIn(OV, s, "stray single overline for %d: %r" % (n, s))
            self.assertEqual(s, ref(n), "mismatch for %d" % n)

    def test_millions_sweep(self):
        for m in range(1, 4000):
            n = m * 1000000
            s = to_roman(n)
            self.assertEqual(s, mark(plain_encode(m), DOV), "wrong for m=%d" % m)
            self.assertNotIn(OV, s)

    def test_structure_random(self):
        rng = random.Random(20240517)
        sample = [4000, 4321, 12345, 99999, 500000, 2500001, 1000000,
                  1999999, 999999999, 3999999999]
        sample += [rng.randint(4000, 3999999999) for _ in range(500)]
        for n in sample:
            s = to_roman(n)
            self.assertTrue(set(s) <= set("IVXLCDM" + OV + DOV),
                            "bad charset for %d: %r" % (n, s))
            self.assertNotIn(MACRON, s)
            self.assertNotIn("MMMM", s)
            g2, g1, g0 = split_groups(s)
            self.assertEqual(parse_plain(g2) if g2 else 0, n // 1000000,
                             "millions group wrong for %d" % n)
            self.assertEqual(parse_plain(g1) if g1 else 0, (n // 1000) % 1000,
                             "thousands group wrong for %d" % n)
            self.assertEqual(parse_plain(g0) if g0 else 0, n % 1000,
                             "units group wrong for %d" % n)
            self.assertLess(parse_plain(g1) if g1 else 0, 1000)
            self.assertLess(parse_plain(g0) if g0 else 0, 1000)
            self.assertEqual(s, ref(n), "mismatch for %d" % n)

    def test_roundtrip_all_small(self):
        for n in range(1, 4000):
            s = to_roman(n)
            self.assertNotIn(OV, s)
            self.assertNotIn(DOV, s)
            self.assertEqual(parse_plain(s), n)
            self.assertEqual(s, ref(n))

    def test_legacy_range_extension(self):
        rng = random.Random(99)
        for n in [4000, 4999, 123456, 999999] + [rng.randint(4000, 999999) for _ in range(200)]:
            s = to_roman(n)
            self.assertNotIn(DOV, s, "unexpected double overline for %d: %r" % (n, s))
            expected = mark(plain_encode(n // 1000), OV) + plain_encode(n % 1000)
            self.assertEqual(s, expected, "mismatch for %d" % n)

    def test_matches_reference(self):
        rng = random.Random(7)
        pool = [4000, 4999, 1000000, 3999999, 4000000, 1000000000, 3999999999]
        pool += [rng.randint(1, 3999999999) for _ in range(400)]
        for n in pool:
            self.assertEqual(to_roman(n), ref(n), "mismatch for %d" % n)

    def test_errors(self):
        for bad in (0, -1, -1000, 4000000000, 10 ** 12):
            with self.assertRaises(ValueError):
                to_roman(bad)

    def test_no_error_inside_range(self):
        self.assertIsInstance(to_roman(1), str)
        self.assertIsInstance(to_roman(4000), str)
        self.assertIsInstance(to_roman(3999999999), str)

const assert = require("assert");
const { page } = require("./solution.js");

const enc = (ts, id) => Buffer.from(`${ts}:${id}`).toString("base64url");
const mk = (ts, id) => ({ ts, id, actor: `u-${id}` });
const events = [
  mk(300, "a1"), mk(250, "b2"),
  mk(200, "c1"), mk(200, "c2"), mk(200, "c3"),
  mk(150, "d1"),
  mk(100, "e1"), mk(100, "e2"),
  mk(50, "f9"),
];
const snapshot = events.map(e => ({ ...e }));
const ids = r => r.items.map(e => e.id);

let r = page(events, null, 2);
assert.deepStrictEqual(ids(r), ["a1", "b2"], "head page");
assert.strictEqual(r.nextCursor, enc(250, "b2"), "head page nextCursor token");

r = page(events, r.nextCursor, 2);
assert.deepStrictEqual(ids(r), ["c1", "c2"], "must stop mid tie group");
assert.strictEqual(r.nextCursor, enc(200, "c2"));
assert.strictEqual(Buffer.from(r.nextCursor, "base64url").toString(), "200:c2", "token round-trip");

r = page(events, enc(200, "c2"), 2);
assert.deepStrictEqual(ids(r), ["c3", "d1"], "resume inside tie group");
assert.strictEqual(r.nextCursor, enc(150, "d1"));

r = page(events, enc(150, "d1"), 3);
assert.deepStrictEqual(ids(r), ["e1", "e2", "f9"], "exact-fit last page");
assert.strictEqual(r.nextCursor, null, "exact-fit last page has no next cursor");

r = page(events, enc(220, "zzz"), 3);
assert.deepStrictEqual(ids(r), ["c1", "c2", "c3"], "compacted key between two events");

r = page(events, enc(200, "c1x"), 2);
assert.deepStrictEqual(ids(r), ["c2", "c3"], "compacted key inside a tie group");

r = page(events, enc(999, "aaa"), 3);
assert.deepStrictEqual(ids(r), ["a1", "b2", "c1"], "key newer than every event");

r = page(events, enc(1, "z"), 3);
assert.deepStrictEqual(r.items, [], "key older than every event");
assert.strictEqual(r.nextCursor, null);

r = page(events, null, 20);
assert.strictEqual(r.items.length, 9);
assert.strictEqual(r.nextCursor, null);

let cur = null, seen = [], iters = 0;
do {
  const p = page(events, cur, 3);
  seen = seen.concat(p.items);
  cur = p.nextCursor;
  iters++;
  assert.ok(iters <= 10, "driver loop did not terminate");
} while (cur !== null);
assert.strictEqual(iters, 3, "full walk takes 3 pages");
assert.deepStrictEqual(seen, events, "full walk must reproduce the log exactly once");

assert.throws(() => page(events, "not-base64!!", 2), TypeError);
assert.throws(() => page(events, Buffer.from("nocolon").toString("base64url"), 2), TypeError);
assert.throws(() => page(events, Buffer.from("abc:ID").toString("base64url"), 2), TypeError);
assert.throws(() => page(events, 42, 2), TypeError);

assert.throws(() => page(events, null, 0), RangeError);
assert.throws(() => page(events, null, -1), RangeError);
assert.throws(() => page(events, null, 2.5), RangeError);

assert.deepStrictEqual(events, snapshot, "input must not be mutated or re-sorted");
console.log("ok");

import unittest
from solution import extract_codes

class T(unittest.TestCase):
    def test_two_codes(self):
        self.assertEqual(extract_codes("[A-01] hello [B-22] world"), ["A-01", "B-22"])
    def test_single(self):
        self.assertEqual(extract_codes("start [Z-99] end"), ["Z-99"])
    def test_none(self):
        self.assertEqual(extract_codes("nothing here"), [])
    def test_adjacent(self):
        self.assertEqual(extract_codes("[A-1][B-2]"), ["A-1", "B-2"])
    def test_nested_simple(self):
        self.assertEqual(extract_codes("[A[B]C]"), ["A[B]C"])
    def test_nested_deep(self):
        self.assertEqual(extract_codes("[a[b[c]d]e] [F]"), ["a[b[c]d]e", "F"])
    def test_escaped_closer(self):
        self.assertEqual(extract_codes("[A\\]B] [C]"), ["A]B", "C"])
    def test_escaped_opener_inside(self):
        self.assertEqual(extract_codes("[x\\[y[z]w]"), ["x[y[z]w"])
    def test_escaped_backslash(self):
        self.assertEqual(extract_codes("[A\\\\] x"), ["A\\"])
    def test_unescape_once(self):
        self.assertEqual(extract_codes("[A\\\\B]"), ["A\\B"])
    def test_escaped_opener_outside(self):
        self.assertEqual(extract_codes("\\[not a code] [X-9]"), ["X-9"])
    def test_stray_closer(self):
        self.assertEqual(extract_codes("] [A-1] ]]"), ["A-1"])
    def test_unclosed(self):
        self.assertEqual(extract_codes("[A-1] [oops"), ["A-1"])
    def test_unclosed_nested(self):
        self.assertEqual(extract_codes("[a[b] tail"), [])
    def test_empty_groups(self):
        self.assertEqual(extract_codes("[] [A] [ ]"), ["A", " "])
    def test_trailing_backslash(self):
        self.assertEqual(extract_codes("[AB\\"), [])
    def test_trailing_backslash_outside(self):
        self.assertEqual(extract_codes("[AB] \\"), ["AB"])
    def test_directive_basic(self):
        self.assertEqual(extract_codes("[!id=A-1] [{id}] [B]"), ["A-1", "B"])
    def test_directive_only(self):
        self.assertEqual(extract_codes("[!a=A]"), [])
    def test_directive_positional(self):
        self.assertEqual(extract_codes("[{id}] [!id=A-1] [{id}]"), ["{id}", "A-1"])
    def test_redefinition(self):
        self.assertEqual(extract_codes("[!p=X] [{p}] [!p=Y] [{p}]"), ["X", "Y"])
    def test_escaped_brace(self):
        self.assertEqual(extract_codes("[!id=A-1] [\\{id}]"), ["{id}"])
    def test_escaped_bang(self):
        self.assertEqual(extract_codes("[\\!id=A-1] [{id}]"), ["!id=A-1", "{id}"])
    def test_invalid_names(self):
        self.assertEqual(extract_codes("[!bad-name=1] [!=1] [{bad-name}]"), ["!bad-name=1", "!=1", "{bad-name}"])
    def test_name_charset(self):
        self.assertEqual(extract_codes("[!A_1=v] [{A_1}] [{A-1}]"), ["v", "{A-1}"])
    def test_non_recursive(self):
        self.assertEqual(extract_codes("[!a={b}] [!b=Z] [{a}]"), ["{b}"])
    def test_brackets_in_value(self):
        self.assertEqual(extract_codes("[!a=[x]] [{a}] [q]"), ["[x]", "q"])
    def test_empty_value(self):
        self.assertEqual(extract_codes("[!a=] [{a}] []"), [""])
    def test_malformed_placeholders(self):
        self.assertEqual(extract_codes("[!a=A] [{} {a-b} {a] [{a}]"), ["{} {a-b} {a", "A"])
    def test_placeholder_in_nested(self):
        self.assertEqual(extract_codes("[!a=A] [p[{a}]q]"), ["p[A]q"])
    def test_escapes_in_value(self):
        self.assertEqual(extract_codes("[!a=\\}] [{a}\\\\{a}]"), ["}\\}"])
    def test_value_not_reunescaped(self):
        self.assertEqual(extract_codes("[!a=\\\\n] [{a}]"), ["\\n"])
    def test_unclosed_after_directive(self):
        self.assertEqual(extract_codes("[!a=A] [unclosed {a}"), [])
    def test_unknown_placeholder(self):
        self.assertEqual(extract_codes("[hello {who}]"), ["hello {who}"])
    def test_multiple_aliases(self):
        self.assertEqual(extract_codes("[!a=1] [!b=2] [{a}-{b}]"), ["1-2"])
